-- Rollback 242: remove the ten inserted BECE beta questions; preserve remediation history.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _expected_242 (question_id TEXT PRIMARY KEY, topic_id TEXT NOT NULL, subject_id TEXT NOT NULL, exam_type_id TEXT NOT NULL, question_text TEXT NOT NULL, question_type TEXT NOT NULL, options TEXT NOT NULL, correct_answer TEXT NOT NULL, explanation TEXT NOT NULL, difficulty TEXT NOT NULL, points INTEGER NOT NULL, marks INTEGER NOT NULL, time_limit INTEGER NOT NULL, command_word TEXT NOT NULL, assessment_objective TEXT NOT NULL);
DELETE FROM _expected_242;
INSERT INTO _expected_242(question_id,topic_id,subject_id,exam_type_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit,command_word,assessment_objective) VALUES
  ('q_bece_math_sets_b001_011','topic_bece_math_sets','subj_bece_math','exam_bece','Which set-builder description represents exactly the natural numbers {2, 4, 6, 8, 10}?','multiple_choice','["A. {x ∈ ℕ : x is even and 2 ≤ x ≤ 10}","B. {x ∈ ℕ : x is odd and x < 10}","C. {x ∈ ℕ : x is a multiple of 3 below 10}","D. {x ∈ ℕ : x is prime and x > 10}"]','A','The listed values are precisely the even natural numbers from 2 through 10 inclusive, as the even-number condition states. Therefore the correct answer is A: {x ∈ ℕ : x is even and 2 ≤ x ≤ 10}.','medium',1,1,90,'Represent','AO2'),
  ('q_bece_math_sets_b001_012','topic_bece_math_sets','subj_bece_math','exam_bece','If C = {red, blue, green}, which statement is false?','multiple_choice','["A. yellow ∈ C","B. red ∈ C","C. blue ∈ C","D. green ∈ C"]','A','The roster lists red, blue and green. Yellow is absent, so the claim that yellow belongs to C is false. Therefore the correct answer is A: yellow ∈ C.','easy',1,1,90,'Identify','AO1'),
  ('q_bece_math_sets_b001_013','topic_bece_math_sets','subj_bece_math','exam_bece','If n(A)=18, n(B)=15 and n(A∩B)=7, find n(A∪B).','multiple_choice','["A. 33","B. 40","C. 26","D. 10"]','C','Use n(A∪B)=n(A)+n(B)−n(A∩B). Thus 18+15−7=26 because overlap is not counted twice. Therefore the correct answer is C: 26.','medium',1,1,90,'Calculate','AO2'),
  ('q_bece_math_sets_b001_014','topic_bece_math_sets','subj_bece_math','exam_bece','Twelve learners play football, nine play volleyball and four play both. How many play at least one?','multiple_choice','["A. 25","B. 21","C. 8","D. 17"]','D','Subtract the overlap once because it appears in both totals: 12 + 9 − 4 = 17 learners. Therefore the correct answer is D: 17.','medium',1,1,90,'Calculate','AO2'),
  ('q_bece_math_sets_b001_015','topic_bece_math_sets','subj_bece_math','exam_bece','Where are elements belonging to both A and B placed in a Venn diagram?','multiple_choice','["A. Outside the universal rectangle","B. The overlapping region","C. The A-only region","D. The B-only region"]','B','The overlap represents intersection A ∩ B, so an element belonging to both sets must be placed there. Therefore the correct answer is B: The overlapping region.','easy',1,1,90,'Identify','AO1'),
  ('q_bece_math_sets_b001_016','topic_bece_math_sets','subj_bece_math','exam_bece','If A ⊆ B and x ∈ A, what must be true?','multiple_choice','["A. x ∉ B","B. x ∈ B","C. B is empty","D. A and B are disjoint"]','B','A ⊆ B means every element of A is also an element of B, so x must belong to B. Therefore the correct answer is B: x ∈ B.','medium',1,1,90,'Deduce','AO2'),
  ('q_bece_math_sets_b001_017','topic_bece_math_sets','subj_bece_math','exam_bece','How many subsets does {p, q} have?','multiple_choice','["A. 4","B. 2","C. 3","D. 8"]','A','A set with n elements has 2ⁿ subsets. Here 2²=4: ∅, {p}, {q} and {p,q}. Therefore the correct answer is A: 4.','medium',1,1,90,'Calculate','AO2'),
  ('q_bece_math_sets_b001_018','topic_bece_math_sets','subj_bece_math','exam_bece','Which set is a subset of every set?','multiple_choice','["A. The universal set","B. {0}","C. The empty set","D. Every two-element set"]','C','The empty set has no member that can violate the subset condition, so it is a subset of every set. Therefore the correct answer is C: The empty set.','medium',1,1,90,'Identify','AO2'),
  ('q_bece_math_sets_b001_019','topic_bece_math_sets','subj_bece_math','exam_bece','If M={1,2,3} and N={3,2,1}, how are they related?','multiple_choice','["A. M is larger","B. They are disjoint","C. M is not a set","D. M = N"]','D','Order does not affect membership. Both rosters contain exactly the same distinct elements, so the sets are equal. Therefore the correct answer is D: M = N.','easy',1,1,90,'Compare','AO1'),
  ('q_bece_math_sets_b001_020','topic_bece_math_sets','subj_bece_math','exam_bece','What does A \ B represent?','multiple_choice','["A. All elements in either set","B. Only common elements","C. Elements in A that are not in B","D. Elements outside both"]','C','Set difference starts with A and removes every element also belonging to B, leaving only A-only elements. Therefore the correct answer is C: Elements in A that are not in B.','medium',1,1,90,'Interpret','AO2');
CREATE TABLE IF NOT EXISTS _rollback_242_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _rollback_242_guard;
INSERT INTO _rollback_242_guard(valid) SELECT CASE WHEN
  NOT EXISTS (SELECT 1 FROM questions q JOIN _expected_242 e ON e.question_id=q.id WHERE NOT (q.id IS e.question_id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective))
  AND NOT EXISTS (SELECT 1 FROM question_content_releases r JOIN _expected_242 e ON e.question_id=r.question_id WHERE NOT (r.batch_id IS 'bece-math-sets-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana’s published NaCCA Common Core Programme curricula; not official WAEC or NaCCA examination material.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1))
  AND NOT EXISTS (SELECT 1 FROM question_bank_remediation_log l JOIN _expected_242 e ON e.question_id=l.entity_id WHERE l.migration_id='242_bece_math_sets_beta_part_2' AND NOT (l.migration_id IS '242_bece_math_sets_beta_part_2' AND l.entity_type IS 'question' AND l.field_name IS 'insert' AND l.old_value IS NULL AND l.new_value IS 'bece-math-sets-beta-001'))
  AND (((SELECT COUNT(*) FROM questions q JOIN _expected_242 e ON e.question_id=q.id WHERE q.id IS e.question_id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective)=10 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _expected_242 e ON e.question_id=r.question_id WHERE r.batch_id IS 'bece-math-sets-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana’s published NaCCA Common Core Programme curricula; not official WAEC or NaCCA examination material.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)=10 AND (SELECT COUNT(*) FROM question_bank_remediation_log l JOIN _expected_242 e ON e.question_id=l.entity_id WHERE l.migration_id IS '242_bece_math_sets_beta_part_2' AND l.entity_type IS 'question' AND l.field_name IS 'insert' AND l.old_value IS NULL AND l.new_value IS 'bece-math-sets-beta-001')=10)
    OR ((SELECT COUNT(*) FROM questions q JOIN _expected_242 e ON e.question_id=q.id)=0 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _expected_242 e ON e.question_id=r.question_id)=0 AND (SELECT COUNT(*) FROM question_bank_remediation_log l JOIN _expected_242 e ON e.question_id=l.entity_id WHERE l.migration_id='242_bece_math_sets_beta_part_2') IN (0,10)))
THEN 1 ELSE 0 END;
DELETE FROM questions WHERE id IN (SELECT question_id FROM _expected_242);
INSERT INTO _rollback_242_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _expected_242 e ON e.question_id=q.id)=0 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _expected_242 e ON e.question_id=r.question_id)=0 THEN 1 ELSE 0 END;
DROP TABLE _expected_242;
DROP TABLE _rollback_242_guard;
